def apply_rules(grid):
    # ... (The previous apply_rules function code is assumed to be available)
    N = len(grid)
    if N < 2:
        return grid

    new_grid = [[grid[i][j] for j in range(N)] for i in range(N)]

    changes = [[0 for _ in range(N)] for _ in range(N)]

    for i in range(N - 1):
        for j in range(N - 1):
            block = [
                grid[i][j], grid[i][j+1],
                grid[i+1][j], grid[i+1][j+1]
            ]

            sum_block = sum(block)

            # Rule 1: Growth (Sum = 3) -> All 4 become 1
            if sum_block == 3:
                for r in range(i, i + 2):
                    for c in range(j, j + 2):
                        changes[r][c] = max(changes[r][c], 1) # Force 1

            # Rule 2: Mutation (Sum = 2) -> All 4 flip state
            elif sum_block == 2:
                for r in range(i, i + 2):
                    for c in range(j, j + 2):
                        current_state = grid[r][c]
                        target_state = 1 - current_state

                        if target_state == 1:
                            changes[r][c] = max(changes[r][c], 1) # Force 1
                        else:
                            changes[r][c] = min(changes[r][c], -1) # Force 0

    # Apply changes
    for i in range(N):
        for j in range(N):
            if changes[i][j] == 1:
                new_grid[i][j] = 1
            elif changes[i][j] == -1:
                new_grid[i][j] = 0
            # If changes[i][j] == 0, new_grid[i][j] remains the same as grid[i][j]

    return new_grid

def count_infected(grid):
    count = 0
    for row in grid:
        count += sum(row)
    return count

def simulate_pattern(initial_grid, max_steps=50):
    grid = [row[:] for row in initial_grid]
    history = [count_infected(grid)]

    for step in range(max_steps):
        next_grid = apply_rules(grid)

        # Check for saturation (all 1s)
        is_full = all(all(cell == 1 for cell in row) for row in next_grid)
        if is_full:
            return True, next_grid

        # Check for stabilization (no change)
        if next_grid == grid:
            return False, next_grid # Stabilized but not full

        # Check for repetition (cycle)
        if count_infected(next_grid) in history:
             # Simple check, more robust cycle detection needed, but for local analysis, this is okay.
             return False, next_grid 

        grid = next_grid
        history.append(count_infected(grid))

    return False, grid

